import assert from 'node:assert/strict'
import { observeEagerReload } from '../packages/db-adapter-conformance/tests/eager-reload-driver'
import { eagerReloadViolations } from '../packages/db-adapter-conformance/tests/eager-reload-oracle'
import { crossElectricReloadAdapter } from '../packages/electric-db-collection/tests/cross-adapter-reload-driver'
import { startAdapterChromium } from '../packages/browser-db-sqlite-persistence/tests/adapter-chromium-host'

async function main() {
  const browser = process.argv.includes('--browser')
  const mutant = !process.argv.includes('--clean')
  const host = browser ? await startAdapterChromium({
    entry: '/packages/electric-db-collection/tests/cross-adapter-receiving.html',
    ready: 'runElectricEagerReload',
  }) : undefined
  try {
    // tsx preserves function names in serialized callbacks with this helper.
    if (host) await host.page.evaluate('globalThis.__name = (value) => value')
    const probe = async (observe: typeof observeEagerReload, violations: typeof eagerReloadViolations, adapter: typeof crossElectricReloadAdapter) => {
      const history = { start: 'fresh' as const, previous: 0, next: 0, mutation: false }
      const raw = await observe({
        async open(initial, id) {
          const sdk = await adapter.open(initial, id)
          const source = sdk.options.sync.sync
          sdk.options = {
            ...sdk.options,
            sync: {
              ...sdk.options.sync,
              sync: (params) => source(mutant ? { ...params, commit: () => true, markReady: () => {} } : params),
            },
          }
          return sdk
        },
      }, history, `electric-empty-no-ready-${crypto.randomUUID()}`)
      return { raw, violations: violations(history, raw) }
    }
    const result = host ? await host.page.evaluate(async (mutant) => {
      const driverUrl = '/packages/db-adapter-conformance/tests/eager-reload-driver.ts'
      const oracleUrl = '/packages/db-adapter-conformance/tests/eager-reload-oracle.ts'
      const adapterUrl = '/packages/electric-db-collection/tests/cross-adapter-reload-driver.ts'
      const { observeEagerReload: observe } = await import(driverUrl)
      const { eagerReloadViolations: violations } = await import(oracleUrl)
      const { crossElectricReloadAdapter: adapter } = await import(adapterUrl)
      const history = { start: 'fresh', previous: 0, next: 0, mutation: false }
      const raw = await observe({
        async open(initial: Array<{id:string;value:number}>, id: string) {
          const sdk = await adapter.open(initial, id)
          const source = sdk.options.sync.sync
          sdk.options = { ...sdk.options, sync: { ...sdk.options.sync,
            sync: (params: Record<string, unknown>) => source(mutant ? { ...params, commit: () => true, markReady: () => {} } : params),
          } }
          return sdk
        },
      }, history, `electric-empty-no-ready-${crypto.randomUUID()}`)
      return { raw, violations: violations(history, raw) }
    }, mutant) : await probe(observeEagerReload, eagerReloadViolations, crossElectricReloadAdapter)
    if (mutant) {
      assert.equal(result.raw.submittedCommits, 0)
      assert.equal(result.raw.sourceReadyCalls, 0)
      assert.equal(result.raw.settledAfterSource, false)
      assert(result.violations.length > 0)
    } else assert.equal(result.violations.length, 0)
    console.log(JSON.stringify({host:browser?'chromium':'node',mutant,classification:mutant?'assertion failure at intended semantic comparison':'clean neighbor passes shared comparison',...result},null,2))
  } finally { await host?.close() }
}
main().catch(error=>{console.error(error);process.exitCode=1})
